	c = _CPU_addcarry_u64(c, a->bitsu64[1], b->bitsu64[1], RES->bitsu64 + 1);
	c = _CPU_addcarry_u64(c, a->bitsu64[2], b->bitsu64[2], RES->bitsu64 + 2);
