	c = _CPU_subborrow_u64(c, RES->bitsu64[0], b, RES->bitsu64 + 0);
	c = _CPU_subborrow_u64(c, RES->bitsu64[1], 0, RES->bitsu64 + 1);
	c = _CPU_subborrow_u64(c, RES->bitsu64[2], 0, RES->bitsu64 + 2);
	c = _CPU_subborrow_u64(c, RES->bitsu64[3], 0, RES->bitsu64 + 3);
